import React, { createContext, useContext, useState, useEffect } from 'react';
import { getData, saveData } from '../services/localStorageService';
import { destinations as sampleDestinations } from '../data/sampleData';
import { generateId } from '../utils/helpers';

const DestinationContext = createContext();

export const DestinationProvider = ({ children }) => {
  const [destinations, setDestinations] = useState([]);

  useEffect(() => {
    const stored = getData('destinations');
    if (stored.length === 0) {
      saveData('destinations', sampleDestinations);
      setDestinations(sampleDestinations);
    } else {
      setDestinations(stored);
    }
  }, []);

  const refresh = () => setDestinations(getData('destinations'));

  const addDestination = (dest) => {
    const newDest = { ...dest, id: generateId() };
    const updated = [...destinations, newDest];
    saveData('destinations', updated);
    setDestinations(updated);
    return newDest;
  };

  const updateDestination = (id, updates) => {
    const updated = destinations.map(d => d.id === id ? { ...d, ...updates } : d);
    saveData('destinations', updated);
    setDestinations(updated);
  };

  const deleteDestination = (id) => {
    const updated = destinations.filter(d => d.id !== id);
    saveData('destinations', updated);
    setDestinations(updated);
  };

  const getDestinationById = (id) => destinations.find(d => d.id === id);

  return (
    <DestinationContext.Provider value={{ destinations, addDestination, updateDestination, deleteDestination, getDestinationById, refresh }}>
      {children}
    </DestinationContext.Provider>
  );
};

export const useDestinations = () => useContext(DestinationContext);
export default DestinationContext;
